@startuml

class Client {
  + NIN : string
  + TIN : string
  + Name : string
  + Address : string
}

class BicycleModel {
  + Name : string
  + Type : BicycleType
  + Gears : int
}

enum BicycleType {
  ROAD
  MOUNTAIN
  BMX
  HYBRID
}

class Bicycle {
  + ID : string
}

class Store {
  + Name : string
  + Address : string
}

class Reservation {
  + PickUpDate : date
}

class Rental {
  + ReturnDate : date
}

BicycleModel "1" -- "*" Bicycle
Client "1" -- "*" Reservation
BicycleModel "1" -- "*" Reservation
Store "1" -- "*" Reservation
Reservation "1" -- "0..1" Rental : results in
Rental "1" -- "1" Bicycle
Rental "1" -- "1" Store : returned to

@enduml

